'use strict';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const escape = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e = escape;
const paths = {
 archive: '<path d="M3 4h18v5H3zM5 9v11h14V9M9 13h6"/>', dashboard: '<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 file: '<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8M8 17h5"/>', folder: '<path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7z"/>',
 inbox: '<path d="M4 4h16l2 12v4H2v-4L4 4zM2 16h6l2 3h4l2-3h6M12 7v6M9 10l3 3 3-3"/>', calendar: '<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2M14 15h2"/>', search: '<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>', plus:'<path d="M12 5v14M5 12h14"/>', chevron:'<path d="m9 5 7 7-7 7"/>', down:'<path d="m6 9 6 6 6-6"/>', upload:'<path d="M12 16V3M7 8l5-5 5 5M4 15v5h16v-5"/>', download:'<path d="M12 3v13M7 11l5 5 5-5M4 16v5h16v-5"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>', check:'<path d="m5 12 4 4L19 6"/>', settings:'<path d="m12 2 2 3 4-1 1 4 3 2-2 3 1 4-4 1-2 3-3-2-4 1-1-4-3-2 2-3-1-4 4-1z"/><circle cx="12" cy="12" r="3"/>', users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M17 15a5 5 0 0 1 4 5"/>', shield:'<path d="M12 3 3 6v6c0 5 9 9 9 9s9-4 9-9V6zM8 12l3 3 5-6"/>', spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>', rules:'<rect x="3" y="3" width="6" height="6" rx="1"/><rect x="15" y="15" width="6" height="6" rx="1"/><path d="M6 9v9h9M9 6h9v9"/>', chart:'<path d="M3 3v18h18M7 16v-5M12 16V7M17 16V4"/>', trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>', mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>', link:'<path d="m10 13 4-4M9 15l-2 2a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0M15 9l2-2a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0"/>', globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18"/>', log:'<path d="M6 3h12v18H6zM9 7h6M9 11h6M9 15h4"/>', close:'<path d="m6 6 12 12M6 18 18 6"/>', moon:'<path d="M20 15a9 9 0 0 1-11-11A9 9 0 1 0 20 15z"/>', sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5 19 19M5 19l1.5-1.5M17.5 6.5 19 5"/>', menu:'<path d="M3 6h18M3 12h18M3 18h18"/>', logout:'<path d="M9 3H4v18h5M10 12h11M17 8l4 4-4 4"/>', refresh:'<path d="M20 7v5h-5M4 17v-5h5M19 8a8 8 0 0 0-14-3M5 16a8 8 0 0 0 14 3"/>', info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>', harddrive:'<path d="m4 4-2 12v4h20v-4L20 4zM2 16h20M17 18h1M5 18h1"/>', key:'<circle cx="8" cy="9" r="5"/><path d="m12 13 8 8M16 17l3-3M18 19l3-3"/>'
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.file}</svg>`;
const roleLabel = {owner:'Eigentümer',manager:'Verwalter',editor:'Bearbeiter',viewer:'Leser'};
const roleLevel = {viewer:0,editor:1,manager:2,owner:3};
const state = {public:{app_name:'Archivraum'},me:null,tenant:null,page:'dashboard',folders:[],stats:null,items:[],total:0,q:'',folder:'',type:'',status:'',offset:0,invitation:new URLSearchParams(location.search).get('invite'),doc:null,theme:localStorage.getItem('dms_theme') || 'light',loadId:0};
const titles = {dashboard:'Übersicht',documents:'Alle Dokumente',inbox:'Posteingang',folders:'Ordner',due:'Fälligkeiten',rules:'Automatische Regeln',integrations:'Integrationen',members:'Mitglieder & Rechte',stats:'Statistiken',audit:'Aktivitätsprotokoll',trash:'Papierkorb',reviews:'Prüfungen',duplicates:'Duplikate',contracts:'Verträge',systemStatus:'Systemzustand',workspaceSettings:'Raumeinstellungen',admin:'Serveradministration'};
const can = role => !!state.tenant && roleLevel[state.tenant.role] >= roleLevel[role];
const base = () => `/api/tenants/${state.tenant.id}`;
const bytes = n => n >= 1073741824 ? (n / 1073741824).toLocaleString('de-DE',{maximumFractionDigits:1})+' GB' : n >= 1048576 ? (n/1048576).toLocaleString('de-DE',{maximumFractionDigits:1})+' MB' : n >= 1024 ? Math.ceil(n/1024)+' KB' : n+' B';
const dateFormat = v => v ? new Date(v.length === 10 ? v+'T12:00:00' : v+'Z').toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit',year:'numeric'}) : '–';
const initials = s => (s||'?').split(/\s+/).slice(0,2).map(p=>p[0]).join('').toUpperCase();
const money = v => v ? Number(String(v).replace(',','.')).toLocaleString('de-DE',{style:'currency',currency:'EUR'}) : '–';
const today = () => new Date().toLocaleDateString('sv-SE');
let fieldSequence=0;
const field = (label,name,value='',type='text',extra='') => {const id='f-'+name+'-'+(++fieldSequence);return `<div class="field"><label for="${id}">${e(label)}</label><input id="${id}" name="${name}" type="${type}" value="${e(value)}" ${extra}></div>`;};
const selectField = (label,name,options,value='') => {const id='f-'+name+'-'+(++fieldSequence);return `<div class="field"><label for="${id}">${e(label)}</label><select id="${id}" name="${name}">${options.map(([v,label])=>`<option value="${e(v)}" ${v===value?'selected':''}>${e(label)}</option>`).join('')}</select></div>`;};
const folderName = id => state.folders.find(f=>f.id===id)?.name || 'Nicht zugeordnet';
const button = (action,label,ico='plus',kind='') => `<button class="btn ${kind}" data-action="${action}">${icon(ico)}${e(label)}</button>`;

async function api(path, options={}) {
  const headers = {...options.headers};
  if (options.body && !(options.body instanceof FormData)) {headers['Content-Type']='application/json';options.body=JSON.stringify(options.body);}
  if (options.method && options.method !== 'GET') headers['X-CSRF-Token'] = decodeURIComponent(document.cookie.split('; ').find(c=>c.startsWith('dms_csrf='))?.slice(9) || '');
  const response = await fetch(path,{...options,headers,credentials:'same-origin'});
  if (!response.ok) {
    let message; try {const data=await response.json();message=typeof data.detail==='string'?data.detail:Array.isArray(data.detail)?data.detail.map(x=>x.msg).join('; '):'Aktion fehlgeschlagen.';} catch {message=await response.text().catch(()=>'Aktion fehlgeschlagen.');}
    if (response.status===401 && !path.includes('/auth/') && !path.includes('/invitations/accept')) {state.me=null;state.tenant=null;$('#modal').close();renderLogin();}
    throw new Error(message || `Fehler ${response.status}`);
  }
  return response.json();
}
function toast(message,error=false) {const div=document.createElement('div');div.className='toast'+(error?' error':'');div.innerHTML=icon(error?'info':'check')+`<span>${e(message)}</span>`;$('#toast-region').append(div);while($('#toast-region').children.length>3)$('#toast-region').firstElementChild.remove();setTimeout(()=>div.remove(),6000);}
function setTheme(theme){state.theme=theme;document.documentElement.dataset.theme=theme;localStorage.setItem('dms_theme',theme);}
function modal(title,html,wide=false){const d=$('#modal');d.className=wide?'modal-wide':'';$('#modal-content').innerHTML=`<div class="modal-header"><h2>${e(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Schließen">${icon('close')}</button></div>${html}`;if(!d.open)d.showModal();applyWidths();}
function empty(title,description,action=''){return `<div class="empty">${icon('archive')}<h3>${e(title)}</h3><p>${e(description)}</p>${action}</div>`;}
function applyWidths() {$$('[data-width]').forEach(el=>{el.style.width=Math.max(0,Math.min(100,Number(el.dataset.width)))+'%';});}
function statusBadge(d){if(d.ai_pending)return `<span class="badge orange">${icon('clock')}KI ausstehend</span>`;const config={ready:['check','Bereit',''],queued:['clock','Warteschlange','orange'],processing:['refresh','Verarbeitung','blue'],error:['info','Fehler','red']};const [ico,label,color]=config[d.status]||['clock',d.status,'gray'];return `<span class="badge ${color}">${icon(ico)}${e(label)}</span>`;}
function typeBadge(type){return `<span class="badge ${type==='Rechnung'?'orange':type==='Vertrag'?'blue':'gray'}">${e(type)}</span>`;}

async function init(){setTheme(state.theme);try{state.public=await api('/api/public');document.title=state.public.app_name;try{state.me=await api('/api/me');}catch{} if(state.me){chooseDefaultTenant();await renderApp();}else if(new URLSearchParams(location.search).has('mfa')){renderMfaLogin();}else{renderLogin();}if(state.invitation)await showInvitation();if(new URLSearchParams(location.search).has('auth_error'))toast('OIDC-Anmeldung fehlgeschlagen. Konfiguration prüfen; bestehende Konten zuerst lokal anmelden.',true);}catch(err){$('#app').innerHTML=empty('Server nicht erreichbar',err.message,button('retry-init','Erneut versuchen','refresh'));}if('serviceWorker' in navigator && window.isSecureContext)navigator.serviceWorker.register('/sw.js').catch(()=>{});}
function chooseDefaultTenant(){state.tenant=state.me.tenants.find(t=>t.id===state.public.domain_tenant)||state.me.tenants.find(t=>t.id===localStorage.getItem('dms_tenant'))||state.me.tenants[0]||null;}
function renderLogin(register=false){$('#app').innerHTML=`<div class="login-shell"><aside class="login-story"><div class="brand"><img src="/static/icon.svg" alt=""><span class="brand-copy">${e(state.public.app_name)}<small>Dokumente. Einfach organisiert.</small></span></div><div class="story"><div class="eyebrow">WENIGER SUCHEN. MEHR ÜBERBLICK.</div><h1>Ihr Archiv.<br>Einfach organisiert.</h1><p>Ein ruhiger Platz für Ihre Dokumente. Sicher aufbewahrt, schnell gefunden und gemeinsam organisiert.</p><div class="login-art"><span>${icon('shield')}Getrennte Dokumentenräume</span><span>${icon('search')}Suche mit Texterkennung</span></div></div><div class="story-foot">Ihre Dokumente. Ihre Infrastruktur.</div></aside><main class="login-panel"><div class="login-form"><div class="eyebrow">WILLKOMMEN IN IHREM ARCHIV</div><h1>${register?'Konto erstellen':'Willkommen zurück.'}</h1><p>${register?'Erstellen Sie Ihr Konto und anschließend Ihren eigenen Dokumentenraum.':'Melden Sie sich an, um Ihre Dokumente zu öffnen.'}</p><div id="auth-error"></div><form data-form="${register?'register':'login'}">${register?field('Ihr Name','name','','text','required maxlength="150" autocomplete="name"'):''}${field('E-Mail-Adresse','email','','email','required autocomplete="username"')}${field('Passwort','password','','password',`required ${register?'minlength="12"':''} autocomplete="${register?'new-password':'current-password'}"`)}${!register&&state.public.ldap_enabled?selectField('Anmeldemethode','method',[['local','Lokales Konto'],['ldap','LDAP / Microsoft AD']]):''}<button class="btn primary" type="submit">${register?'Konto erstellen':'Anmelden'}${icon('chevron')}</button></form>${!register&&state.public.oidc_enabled?'<a class="btn" href="/api/auth/oidc">'+icon('key')+'Mit Single Sign-on anmelden</a>':''}${state.public.registration_enabled?`<button class="btn text" data-action="${register?'show-login':'show-register'}">${register?'Bereits ein Konto? Anmelden':'Neues Konto erstellen'}</button>`:''}<div class="login-meta">${state.public.registration_enabled?'Dokumentenräume mit sicheren Zugriffsrechten.':'Ein neues Konto erhalten Sie über eine Einladung.'}</div></div></main></div>`;}
function navItem(page,ico,label,count=null){return `<button data-page="${page}" class="${state.page===page?'active':''}">${icon(ico)}<span>${e(label)}</span>${count!==null?`<span class="count">${count}</span>`:''}</button>`;}
function renderShell(){const s=state.stats;$('#app').innerHTML=`<div class="shell"><button class="menu-backdrop" data-action="mobile-menu" aria-label="Menü schließen"></button><aside class="sidebar"><button class="sidebar-close icon-button" data-action="mobile-menu" aria-label="Seitenleiste schließen">${icon('close')}</button><a class="brand" href="/" aria-label="Startseite"><img src="/static/icon.svg" alt=""><span class="brand-copy">${e(state.public.app_name)}<small>Dokumente. Einfach organisiert.</small></span></a><button class="workspace" data-action="switch-tenant"><div class="workspace-icon">${icon('archive')}</div><span><small>Dokumentenraum</small><strong>${e(state.tenant?.name||'Raum erstellen')}</strong></span>${icon('down')}</button><div class="nav-label">Arbeitsbereich</div><nav class="nav" aria-label="Hauptnavigation">${navItem('dashboard','dashboard','Übersicht')}${navItem('documents','file','Alle Dokumente',s?.documents??null)}${navItem('inbox','inbox','Posteingang')}${navItem('folders','folder','Ordner')}${navItem('due','calendar','Fälligkeiten',s?.overdue||null)}${navItem('contracts','calendar','Vertragsverwaltung')}${navItem('duplicates','file','Duplikate')}${state.tenant?.workflow_enabled?navItem('reviews','check','Prüfungen'):''}<div class="nav-separator"></div><div class="nav-label">Organisieren</div>${navItem('rules','rules','Automatische Regeln')}${navItem('stats','chart','Statistiken')}${can('manager')?navItem('members','users','Mitglieder & Rechte'):''}${can('owner')?navItem('integrations','link','Integrationen'):''}${can('owner')?navItem('audit','log','Aktivitätsprotokoll'):''}${can('owner')?navItem('workspaceSettings','settings','Raumeinstellungen'):''}${navItem('trash','trash','Papierkorb')}</nav><div class="sidebar-bottom">${state.me.admin?`<nav class="nav server-link">${navItem('admin','settings','Serveradministration')}${navItem('systemStatus','harddrive','Systemzustand')}</nav>`:''}<button class="user-button" data-action="account"><div class="avatar">${e(initials(state.me.name))}</div><span><strong>${e(state.me.name)}</strong><small>${state.tenant?roleLabel[state.tenant.role]:'Konto'}</small></span>${icon('down')}</button></div></aside><main class="main"><header class="topbar"><button class="icon-button mobile-menu" data-action="mobile-menu" aria-label="Menü öffnen">${icon('menu')}</button><div class="breadcrumb">${icon('archive')}<span>${e(state.tenant?.name||'Arbeitsbereich')}</span>${icon('chevron')}<b>${e(titles[state.page])}</b></div><div class="top-actions"><form class="search-field" data-form="global-search">${icon('search')}<input type="search" name="q" placeholder="Dokumente durchsuchen" aria-label="Dokumente durchsuchen" value="${e(state.q)}"><kbd>⌘ K</kbd></form><button class="icon-button" data-action="theme" aria-label="Theme wechseln">${icon(state.theme==='dark'?'sun':'moon')}</button><button class="icon-button" data-page="due" aria-label="Fälligkeiten">${icon('calendar')}</button></div></header><div class="content" id="content"><div class="skeleton">Dokumente werden geladen …</div></div></main></div>`;}
async function renderApp(){state.loadId++;const id=state.loadId; if(state.tenant){try{[state.stats,state.folders]=await Promise.all([api(base()+'/stats'),api(base()+'/folders')]);}catch(err){toast(err.message,true);return;}}renderShell();if(!state.tenant&&!['admin','systemStatus'].includes(state.page)){renderOnboarding();return;}await renderPage(id);}
function renderOnboarding(){$('#content').innerHTML=`<div class="onboarding"><div class="large-symbol">${icon('archive')}</div><div class="eyebrow">IHR ARCHIV BEGINNT HIER</div><h1>Ein Raum für alles Wichtige.</h1><p>Erstellen Sie Ihren ersten Dokumentenraum. Laden Sie Dokumente hoch und geben Sie Ihrem Team genau die Rechte, die es braucht.</p>${state.me.tenant_creation_enabled||state.me.admin?button('new-tenant','Dokumentenraum erstellen','plus','primary')+'<button class="btn" data-feature-action="restore-backup">Sicherung wiederherstellen</button>':''}<div class="onboarding-steps"><div><b>01</b><h3>Dokumente sammeln</h3><p>PDFs, Scans und E-Mails an einem zentralen Ort.</p></div><div><b>02</b><h3>Automatisch ordnen</h3><p>Texterkennung und eigene Regeln übernehmen die Ablage.</p></div><div><b>03</b><h3>Gemeinsam arbeiten</h3><p>Mitglieder einladen und Zugriffsrechte festlegen.</p></div></div></div>`;}
function heading(title,subtitle,actions='',eyebrow='IHR DOKUMENTENRAUM'){return `<div class="page-heading"><div><div class="eyebrow">${e(eyebrow)}</div><h1>${e(title)}</h1><p class="subtitle">${e(subtitle)}</p></div><div class="heading-actions">${actions}</div></div>`;}
function metrics(){const s=state.stats;return `<div class="metrics"><div class="metric"><div class="metric-label">Dokumente insgesamt${icon('file')}</div><div class="metric-value">${s.documents.toLocaleString('de-DE')}</div><div class="metric-foot"><span class="dot"></span>Sicher in Ihrem Dokumentenraum</div></div><div class="metric"><div class="metric-label">Speicher belegt${icon('harddrive')}</div><div class="metric-value">${bytes(s.bytes)}</div><div class="metric-foot">von ${bytes(s.quota_mb*1048576)} verfügbar</div></div><div class="metric"><div class="metric-label">Offene Fälligkeiten${icon('calendar')}</div><div class="metric-value">${s.due}</div><div class="metric-foot"><span class="dot ${s.overdue?'orange':''}"></span>${s.overdue?s.overdue+' bereits überfällig':'Alles im Blick'}</div></div><div class="metric"><div class="metric-label">In Verarbeitung${icon('spark')}</div><div class="metric-value">${s.queued}</div><div class="metric-foot">${s.errors?s.errors+' Dokumente mit Fehlern':'OCR und Ablageregeln'}</div></div></div>`;}
function documentsTable(items,compact=false){if(!items.length)return empty('Noch keine Dokumente',state.q?'Für diese Suche wurden keine Dokumente gefunden.':'Laden Sie Ihr erstes Dokument hoch. Die Texterkennung startet automatisch.',can('editor')?button('upload','Dokument hochladen','upload','primary'):'');return `<div class="table-wrap"><table><thead><tr>${selectableDocuments(compact)?'<th class="select-cell"><input type="checkbox" data-select-all aria-label="Alle angezeigten Dokumente auswählen"></th>':''}<th>Dokument</th><th>Typ</th>${!compact?'<th>Lieferant</th><th>Ordner</th>':''}<th>Hinzugefügt</th><th>Status</th><th></th></tr></thead><tbody>${items.map(d=>`<tr data-doc="${d.id}">${selectableDocuments(compact)?`<td class="select-cell"><input type="checkbox" data-select-doc="${d.id}" aria-label="${e(d.title)} auswählen"></td>`:''}<td><div class="doc-cell"><div class="file-icon ${d.mime.startsWith('image')?'blue':''}">${d.mime==='application/pdf'?'PDF':d.mime.startsWith('image')?'IMG':'TXT'}</div><div><div class="doc-title">${e(d.title)}</div><div class="doc-sub">${e(d.filename)} · ${bytes(d.size)}</div></div></div></td><td>${typeBadge(d.doc_type)}</td>${!compact?`<td>${e(d.supplier||'–')}</td><td>${e(folderName(d.folder_id))}</td>`:''}<td>${dateFormat(d.created_at)}</td><td>${statusBadge(d)}</td><td><button class="icon-button" data-open-doc="${d.id}" aria-label="Dokument öffnen">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function storageCard(){const s=state.stats;return `<div class="card storage-card"><div class="storage-title">${icon('shield')}Ihr Speicherplatz</div><div class="progress"><div class="progress-bar" data-width="${s.bytes/(s.quota_mb*1048576)*100}"></div></div><div class="storage-info"><span>${bytes(s.bytes)} belegt</span><span>${bytes(s.quota_mb*1048576)}</span></div></div>`;}
async function renderPage(id=state.loadId){try{let html='';switch(state.page){case 'dashboard':{const result=await api(base()+'/documents?limit=6');state.items=result.items;html=heading('Alles im Blick.','Ihre Dokumente, Ablage und Termine – übersichtlich an einem Ort.',can('editor')?button('upload','Dokument hochladen','plus','primary')+cameraButton():'')+metrics()+`<div class="hero"><div><div class="eyebrow">INTELLIGENTE ABLAGE</div><h2>Mehr Ordnung. Weniger Handarbeit.</h2><p>Lassen Sie Texte automatisch erkennen und Dokumente mit eigenen Regeln in die passende Ablage sortieren.</p>${button(can('manager')?'new-rule':'all-documents',can('manager')?'Ablageregel erstellen':'Dokumente ansehen',can('manager')?'rules':'file','small')}</div><div class="hero-visual" aria-hidden="true"><div class="workflow-step">${icon('spark')}<span>Erkennen</span></div><span class="workflow-connector"></span><div class="workflow-step">${icon('folder')}<span>Sortieren</span></div><span class="workflow-connector"></span><div class="workflow-step">${icon('search')}<span>Finden</span></div></div></div><div class="two-columns"><section class="card"><div class="card-header"><div><h2>Zuletzt hinzugefügt</h2><p>Die neuesten Dokumente in Ihrem Archiv</p></div><button class="btn text small" data-page="documents">Alle ansehen ${icon('chevron')}</button></div>${documentsTable(result.items,true)}<div class="card-footer"><span>${state.stats.documents} Dokumente in Ihrem Archiv</span><span>Originale bleiben erhalten</span></div></section><aside class="side-stack"><section class="card"><div class="card-header"><h2>Ihre Ordner</h2><button class="btn text small" data-page="folders" aria-label="Alle Ordner">${icon('chevron')}</button></div><div class="folder-list">${state.folders.slice(0,4).map(f=>`<button class="folder-row" data-folder="${f.id}">${icon('folder')}<span>${e(f.name)}</span><span>${f.count}</span></button>`).join('')}</div></section>${storageCard()}${can('editor')?`<div class="upload-box" data-action="upload" data-drop="upload" role="button" tabindex="0"><div class="upload-circle">${icon('upload')}</div><h3>Einfach hier ablegen</h3><p>PDF, Bilder oder Text · bis ${state.public.max_upload_mb} MB</p></div>`:''}</aside></div>`;break;}
case 'documents':case 'inbox':case 'trash':{if(state.page==='inbox')state.folder=state.folders.find(f=>f.name==='Eingang')?.id||'';let params=new URLSearchParams({q:state.q,offset:state.offset,limit:50,folder:state.folder,doc_type:state.type,status:state.status,trash:state.page==='trash'});const result=await api(base()+'/documents?'+params);state.items=result.items;state.total=result.total;html=heading(state.folder&&state.page==='documents'?folderName(state.folder):titles[state.page],state.page==='trash'?'Gelöschte Dokumente bleiben erhalten und können wiederhergestellt werden.':state.page==='inbox'?'Neue Dokumente prüfen und in die passende Ablage einordnen.':'Ihre Dokumente. Durchsuchbar, sortiert und immer griffbereit.',can('editor')&&state.page!=='trash'?button('upload','Dokument hochladen','plus','primary')+cameraButton():'')+`<section class="card"><form class="filters" data-form="filter"><input type="search" name="q" placeholder="Titel, Lieferant oder Dokumenttext …" value="${e(state.q)}" aria-label="Dokumente suchen"><select name="doc_type" aria-label="Dokumenttyp"><option value="">Alle Dokumenttypen</option>${['Rechnung','Vertrag','Lieferschein','Sonstiges'].map(t=>`<option ${state.type===t?'selected':''}>${t}</option>`).join('')}</select><select name="folder" aria-label="Ordner" ${state.page==='inbox'?'disabled':''}><option value="">Alle Ordner</option>${state.folders.map(f=>`<option value="${f.id}" ${state.folder===f.id?'selected':''}>${e(f.name)}</option>`).join('')}</select><select name="status" aria-label="Status"><option value="">Alle Status</option>${[['ready','Bereit'],['queued','Warteschlange'],['processing','Verarbeitung'],['error','Fehler']].map(([v,l])=>`<option value="${v}" ${state.status===v?'selected':''}>${l}</option>`).join('')}</select><button class="btn small">Filtern</button><button type="button" class="btn text small" data-action="clear-filter">Zurücksetzen</button></form>${bulkToolbar()}${documentsTable(result.items)}<div class="card-footer"><span>${result.total} Dokumente${state.q?' für „'+e(state.q)+'“':''}</span><div>${button('prev-page','Zurück','chevron','small')}${button('next-page','Weiter','chevron','small')}</div></div></section>`;break;}
case 'folders':html=heading('Ordnung, die zu Ihnen passt.','Organisieren Sie Ihre Ablage nach Lieferant, Thema oder Dokumenttyp.',can('manager')?button('new-folder','Ordner erstellen','plus','primary'):'')+`<div class="folder-grid">${state.folders.map(f=>`<div class="folder-card"><button class="btn text" data-folder="${f.id}" aria-label="Ordner ${e(f.name)} öffnen">${icon('folder')}</button><strong>${e(f.name)}</strong><p>${f.count} Dokumente</p><div class="form-actions"><button class="btn text small" data-folder="${f.id}">Öffnen ${icon('chevron')}</button>${can('owner')?`<button class="btn small" data-feature-action="access" data-kind="folders" data-id="${f.id}">${icon('shield')}Zugriff</button>`:''}${can('manager')?`<button class="icon-button" data-remove-folder="${f.id}" aria-label="Ordner löschen">${icon('trash')}</button>`:''}</div></div>`).join('')}</div><div class="callout">${icon('info')}Ordner bilden die logische Ablage. Ihre Originaldateien bleiben unverändert im sicheren Speicher des Dokumentenraums.</div>`;break;
case 'due':{const result=await api(base()+'/documents?due=true&limit=100');state.items=result.items;result.items.sort((a,b)=>a.due_date.localeCompare(b.due_date));html=heading('Wichtiges zur richtigen Zeit.','Offene Rechnungen und Dokumente mit Fälligkeit.',button('refresh-page','Aktualisieren','refresh'))+`<div class="due-list">${result.items.length?result.items.map(d=>`<div class="card due-item"><div class="date-tile"><strong>${d.due_date.slice(8)}</strong><span>${new Date(d.due_date+'T12:00').toLocaleDateString('de-DE',{month:'short',year:'2-digit'})}</span></div><div class="due-meta"><button class="btn text" data-open-doc="${d.id}"><h3>${e(d.title)}</h3></button><p>${e(d.supplier||'Kein Lieferant')} · ${e(folderName(d.folder_id))}</p></div><div class="amount">${money(d.amount)}</div><span class="badge ${d.due_date<today()?'red':'orange'}">${d.due_date<today()?'Überfällig':'Offen'}</span>${can('editor')?`<button class="btn small" data-paid="${d.id}">${icon('check')}Als bezahlt markieren</button>`:''}</div>`).join(''):empty('Keine offenen Fälligkeiten','Fälligkeiten hinterlegen Sie direkt in den Dokumentdetails.')}</div>${result.total>100?'<div class="callout">Es werden die neuesten 100 offenen Dokumente angezeigt. Weitere Dokumente finden Sie über die Suche.</div>':''}<div class="callout">${icon('calendar')}Mit einer CalDAV-Verbindung werden Fälligkeiten automatisch als ganztägige Termine in Ihren Kalender übertragen.</div>`;break;}
case 'rules':{const rules=await api(base()+'/rules');state.rules=rules;html=heading('Passende Namen. Automatische Ablage.','Regeln benennen Dokumente um und ordnen sie dem passenden Ordner zu.',can('manager')?button('new-rule','Regel erstellen','plus','primary'):'')+`<div class="list-cards">${rules.length?rules.map(r=>`<div class="card rule-card"><div class="rule-body"><div class="rule-icon">${icon(r.filename_template?'file':'rules')}</div><div><h3>${e(r.name)}</h3><p>${r.field==='all'?'Für alle Dokumente':`Wenn <b>${e({text:'Dokumenttext',supplier:'Lieferant',doc_type:'Dokumenttyp',title:'Titel',filename:'Dateiname'}[r.field])}</b> „${e(r.contains)}“ enthält`}</p>${r.folder_id?`<p>${icon('folder')} Ablage: ${e(folderName(r.folder_id))}</p>`:''}${r.filename_template?`<p class="rule-template">${icon('file')} Dateiname: <code>${e(r.filename_template)}</code></p>`:''}<p>Priorität ${r.priority} · ${r.enabled?'Aktiv':'Pausiert'}</p></div></div>${can('manager')?`<button class="btn small" data-edit-rule="${r.id}">Bearbeiten</button><button class="icon-button" data-remove-rule="${r.id}" aria-label="Regel löschen">${icon('trash')}</button>`:''}</div>`).join(''):empty('Ihr Archiv kann mitdenken.','Benennen Sie Rechnungen automatisch nach Lieferant und Datum oder legen Sie sie in einem passenden Ordner ab.',can('manager')?button('new-rule','Erste Regel erstellen','rules','primary'):'')}</div><div class="callout">${icon('info')}Regeln laufen nach OCR und KI-Auswertung. Pro Aktion gewinnt die erste passende Regel; kleinere Prioritätszahlen zuerst. Fehlende Angaben in einer Namensvorlage werden abgewartet. Bedingungen für Dateinamen berücksichtigen auch den Originalnamen.</div>${can('manager')?button('apply-rules','Auf bestehende Dokumente anwenden','refresh'):''}`;break;}
case 'integrations':{const configs=await api(base()+'/integrations');state.integrations=configs;html=heading('Ihr Archiv kann mehr.','Importieren Sie Scans automatisch und verbinden Sie E-Mail, Kalender oder KI.')+`<div class="integration-grid">${[['folder','inbox','Scanner-Importordner','Scans automatisch übernehmen. Quelldateien anschließend löschen oder in Verarbeitet verschieben.'],['imap','mail','E-Mail-Import','Anhänge und auf Wunsch E-Mail-Texte aus einem IMAP-Postfach automatisch importieren.'],['caldav','calendar','CalDAV-Kalender','Offene Fälligkeiten mit Ihrem Kalender synchronisieren. Bezahlte Rechnungen werden entfernt.'],['ai','spark','KI-Metadaten','Lieferanten, Dokumenttypen, Beträge und Fälligkeiten aus erkanntem Text extrahieren.']].map(([kind,ico,title,desc])=>{const c=configs.find(c=>c.kind===kind);return `<section class="card integration-card"><div class="integration-logo">${icon(ico)}</div><h2>${title}</h2><p>${desc}</p><span class="badge ${c?.enabled?'':'gray'}">${c?.enabled?'Aktiv':'Nicht verbunden'}</span>${kind==='folder'&&c?.enabled?`<div class="import-path"><small>Scanner-Zielordner</small><code>${e(c.paths.incoming)}</code></div>`:''}${c?.errors?.length?`<p class="import-errors">${c.errors.length} zurückbehaltene Datei${c.errors.length===1?'':'en'}. Details unter Konfigurieren.</p>`:''}${kind==='ai'&&c?.enabled?`<p class="privacy-mode">${e(c.config?.privacy_mode==='automatic'?'Automatische KI · Maskierung aktiv':'Manuelle KI · Vorschau erforderlich')}</p>`:''}${c?.last_run?`<small>Zuletzt: ${dateFormat(c.last_run)}<br>${e(c.last_status)}</small>`:''}<button class="btn" data-integration="${kind}">${icon('settings')}Konfigurieren</button>${c?.enabled&&kind!=='ai'?`<button class="btn small" data-run-integration="${kind}">${icon('refresh')}${kind==='folder'?'Ordner jetzt prüfen':'Jetzt synchronisieren'}</button>`:''}</section>`;}).join('')}</div><div class="callout">${icon('shield')}OCR und Ablageregeln laufen auf Ihrem Server. Die KI ist standardmäßig deaktiviert. Die automatische KI-Auswertung läuft nach dem Import mit Maskierung und Textgrenze. Eine manuelle Vorschau bleibt wählbar. Die PWA speichert keine privaten Dokumente für den Offlinebetrieb.</div>`;break;}
case 'members':{const members=await api(base()+'/members');state.members=members;html=heading('Gemeinsam gut organisiert.','Laden Sie Mitglieder ein und vergeben Sie passende Rechte.',button('new-invite','Mitglied einladen','plus','primary'))+`<section class="card"><div class="table-wrap"><table><thead><tr><th>Mitglied</th><th>E-Mail-Adresse</th><th>Rolle</th><th>Aktionen</th></tr></thead><tbody>${members.map(m=>`<tr><td><div class="doc-cell"><div class="avatar">${e(initials(m.name))}</div><strong>${e(m.name)}${m.id===state.me.id?' (Sie)':''}</strong></div></td><td>${e(m.email)}</td><td><span class="badge">${roleLabel[m.role]}</span></td><td>${can('owner')?`<button class="btn text small" data-role-user="${m.id}">Rechte ändern</button>`:''}${roleLevel[state.tenant.role]>roleLevel[m.role]?`<button class="icon-button" data-remove-member="${m.id}" aria-label="Mitglied entfernen">${icon('trash')}</button>`:''}</td></tr>`).join('')}</tbody></table></div></section><div class="callout">${icon('users')}Leser öffnen und laden Dokumente herunter. Bearbeiter verwalten Dokumente. Verwalter verwalten zusätzlich Ordner, Regeln und Mitglieder. Eigentümer verwalten alle Mandanteneinstellungen und Integrationen.</div>${can('owner')?`<section class="card settings-card"><h2>Dokumentenraum benennen</h2><form data-form="rename-tenant">${field('Name','name',state.tenant.name,'text','required maxlength="150"')}<button class="btn">Namen speichern</button></form></section>`:''}`;break;}
case 'stats':{const s=state.stats;const max=Math.max(1,...Object.values(s.types));const maxMonths=Math.max(1,...Object.values(s.months));html=heading('Ihr Archiv in Zahlen.','Dokumentenarten, Speicherverbrauch und die Entwicklung Ihrer Ablage.')+metrics()+`<div class="charts"><section class="card chart"><h2>Dokumenttypen</h2>${Object.keys(s.types).length?Object.entries(s.types).map(([k,n])=>`<div class="bar-row"><span>${e(k)}</span><div class="bar-track"><div class="bar-fill" data-width="${n/max*100}"></div></div><span>${n}</span></div>`).join(''):empty('Noch keine Daten','Statistiken entstehen mit Ihren ersten Dokumenten.')}</section><section class="card chart"><h2>Hinzugefügte Dokumente pro Monat</h2>${Object.keys(s.months).length?Object.entries(s.months).sort().slice(-12).map(([k,n])=>`<div class="bar-row"><span>${new Date(k+'-15').toLocaleDateString('de-DE',{month:'short',year:'numeric'})}</span><div class="bar-track"><div class="bar-fill" data-width="${n/maxMonths*100}"></div></div><span>${n}</span></div>`).join(''):empty('Das Archiv wächst mit Ihnen.','Hier sehen Sie später den Verlauf Ihrer Dokumenteneingänge.')}</section>${storageCard()}<section class="card settings-card"><h2>Zusammenarbeit</h2><div class="metric-value">${s.members}</div><p>Mitglieder in Ihrem Dokumentenraum</p></section></div>`;break;}
case 'audit':{const rows=await api(base()+'/audit');html=heading('Änderungen bleiben nachvollziehbar.','Die letzten 100 Aktivitäten in diesem Dokumentenraum.')+`<section class="card"><div class="table-wrap"><table><thead><tr><th>Zeitpunkt</th><th>Mitglied</th><th>Aktion</th><th>Details</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${dateFormat(r.at)} ${new Date(r.at+'Z').toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})}</td><td>${e(r.actor)}</td><td>${e(actionLabel(r.action))}</td><td>${e(r.detail)}</td></tr>`).join('')}</tbody></table></div></section>`;break;}
case 'duplicates':html=await renderDuplicates();break;case 'contracts':html=await renderContracts();break;case 'systemStatus':html=await renderSystemStatus();break;case 'workspaceSettings':html=await renderWorkspaceSettings();break;case 'reviews':html=await renderReviews();break;case 'admin':html=await renderAdmin();break;
}if(id!==state.loadId)return;$('#content').innerHTML=html+`<div class="footer-note">${e(state.public.app_name)} · Ihre Dokumente. Ihre Infrastruktur.</div>`;applyWidths();if(state.page==='documents'||state.page==='trash'||state.page==='inbox'){const prev=$('[data-action="prev-page"]');const next=$('[data-action="next-page"]');if(prev)prev.disabled=!state.offset;if(next)next.disabled=state.offset+50>=state.total;}}catch(err){if(id===state.loadId&&$('#content'))$('#content').innerHTML=empty('Ansicht konnte nicht geladen werden',err.message,button('refresh-page','Erneut versuchen','refresh'));}}
function actionLabel(action){return ({'version.created':'Neue Dokumentversion angelegt','version.downloaded':'Dokumentversion heruntergeladen','documents.access_changed':'Dokumentrechte geändert','folders.access_changed':'Ordnerrechte geändert','workflow.configured':'Prüfabläufe geändert','review.requested':'Prüfung angefordert','review.approved':'Dokument freigegeben','review.rejected':'Dokument zurückgewiesen','review.cancelled':'Prüfung abgebrochen','document.camera_scan':'Kamera-Scan importiert','tenant.backup_exported':'Verschlüsselte Raumsicherung erstellt','tenant.backup_restored':'Raumsicherung wiederhergestellt','tenant.created':'Dokumentenraum erstellt','tenant.renamed':'Dokumentenraum umbenannt','folder.created':'Ordner erstellt','folder.deleted':'Ordner gelöscht','document.uploaded':'Dokument hochgeladen','document.imported':'Scan importiert','document.updated':'Dokument bearbeitet','document.downloaded':'Dokument heruntergeladen','document.trashed':'In Papierkorb verschoben','document.restored':'Dokument wiederhergestellt','document.processed':'Dokument verarbeitet','document.reprocess':'Verarbeitung erneut gestartet','document.ai_approved':'KI-Vorschau freigegeben','document.ai_requested':'Minimierten Text an KI übertragen','document.ai_completed':'KI-Metadaten übernommen','document.ai_failed':'KI-Auswertung fehlgeschlagen','invitation.created':'Einladung erstellt','invitation.accepted':'Einladung angenommen','member.role_changed':'Berechtigung geändert','member.removed':'Mitglied entfernt','rule.created':'Regel erstellt','rule.updated':'Regel geändert','rule.deleted':'Regel gelöscht','rules.applied':'Regeln angewendet','integration.configured':'Integration konfiguriert','integration.run':'Synchronisierung gestartet'})[action]||action;}
async function renderAdmin(){const [data,codex]=await Promise.all([api('/api/admin'),api('/api/admin/codex')]);state.admin=data;return heading('Die Zentrale für Ihren Server.','Systemeinstellungen, Domains, Authentifizierung und Mandanten.', '', 'SERVERADMINISTRATION')+`<div class="settings-grid"><section class="card settings-card"><h2>Allgemeine Einstellungen</h2><form data-form="settings">${field('Name der Anwendung','app_name',data.settings.app_name,'text','required maxlength="80"')}<label class="checkbox"><input type="checkbox" name="registration_enabled" ${data.settings.registration_enabled?'checked':''}>Öffentliche Registrierung erlauben</label><label class="checkbox"><input type="checkbox" name="tenant_creation_enabled" ${data.settings.tenant_creation_enabled?'checked':''}>Benutzer dürfen eigene Dokumentenräume erstellen</label><label class="checkbox"><input type="checkbox" name="ai_external_blocked" ${data.settings.ai_external_blocked?'checked':''}>Alle externen KI-Übertragungen sperren</label><div class="form-actions"><button class="btn primary">Einstellungen speichern</button></div></form></section><section class="card settings-card"><h2>Systemstatus</h2>${[['Datenbank',data.system.database==='mysql'?'MariaDB / MySQL':data.system.database],['Dokumentenablage',data.system.storage],['Speicherzugriff',data.system.storage_writable?'Schreibbar':'Nicht schreibbar'],['Upload-Limit',data.system.max_upload_mb+' MB'],['HTTPS-Cookies',data.system.cookie_secure?'Aktiv':'HTTP-Testbetrieb']].map(([k,v])=>`<div class="system-row"><span>${e(k)}</span><b>${e(v)}</b></div>`).join('')}</section><section class="card settings-card"><h2>Domains</h2><p>Mehrere Domains können dieselbe Instanz öffnen. Eine Zuordnung legt den bevorzugten Dokumentenraum fest; Zugriffsrechte gelten weiterhin.</p><div class="table-wrap"><table class="domain-table"><tbody>${data.domains.map(d=>`<tr><td>${e(d.host)}<div class="doc-sub">${e(data.tenants.find(t=>t.id===d.tenant_id)?.name||'Alle Dokumentenräume')}</div></td><td><button class="icon-button" data-remove-domain="${e(d.host)}" aria-label="Domain entfernen">${icon('trash')}</button></td></tr>`).join('')}</tbody></table></div><div class="form-actions">${button('new-domain','Domain hinzufügen','globe')}</div></section><section class="card settings-card"><h2>Verzeichnis & Single Sign-on</h2><p>Nutzen Sie LDAP / Microsoft AD oder einen OIDC-Anbieter wie Keycloak oder Microsoft Entra ID.</p><div class="form-actions"><button class="btn" data-auth-config="ldap">${icon('users')}LDAP / AD</button><button class="btn" data-auth-config="oidc">${icon('key')}OIDC</button></div></section><section class="card settings-card codex-settings"><h2>Codex · ChatGPT-Abonnement</h2><div id="codex-status">${codexStatusHtml(codex)}</div><p>Geben Sie frei, welche Dokumentenräume Ihr verbundenes Abonnement für die KI-Auswertung nutzen dürfen. Jeder Raum aktiviert die Auswertung anschließend selbst.</p><form data-form="codex-tenants">${data.tenants.map(t=>`<label class="checkbox"><input type="checkbox" name="tenant_ids" value="${t.id}" ${codex.allowed_tenants.includes(t.id)?'checked':''}>${e(t.name)}</label>`).join('')}<div class="form-actions"><button class="btn primary">Mandantenfreigaben speichern</button></div></form></section></div><div class="section-row"><h2>Dokumentenräume</h2><span class="count-note">${data.tenants.length} Mandanten</span></div><section class="card"><div class="table-wrap"><table><thead><tr><th>Dokumentenraum</th><th>Mitglieder</th><th>Speicher belegt</th><th>Speicherlimit</th><th></th></tr></thead><tbody>${data.tenants.map(t=>`<tr><td><strong>${e(t.name)}</strong></td><td>${t.members}</td><td>${bytes(t.bytes)}</td><td>${bytes(t.quota_mb*1048576)}</td><td><button class="btn text small" data-quota="${t.id}">Limit ändern</button></td></tr>`).join('')}</tbody></table></div>${!data.tenants.length?empty('Noch keine Dokumentenräume','Benutzer können eigene Mandanten anlegen.') : ''}</section><div class="section-row"><h2>Benutzerkonten</h2><span class="count-note">${data.users.length} Konten</span></div><section class="card"><div class="table-wrap"><table><thead><tr><th>Name</th><th>E-Mail</th><th>Kontostatus</th><th></th></tr></thead><tbody>${data.users.map(u=>`<tr><td>${e(u.name)}${u.admin?' <span class="badge">Serveradmin</span>':''}</td><td>${e(u.email)}</td><td><span class="badge ${u.active?'':'red'}">${u.active?'Aktiv':'Gesperrt'}</span></td><td>${!u.admin?`<button class="btn text small" data-toggle-user="${u.id}">${u.active?'Sperren':'Freigeben'}</button>`:''}</td></tr>`).join('')}</tbody></table></div></section><div class="callout">${icon('info')}Datenbankverbindung und NAS-Mount werden über die Docker-Konfiguration eingerichtet. Domain-Einträge ersetzen keine DNS- oder TLS-Konfiguration.</div>`;}
function formModal(title,name,fields,submit='Speichern',intro=''){modal(title,`<div class="modal-body">${intro?`<p>${e(intro)}</p>`:''}<form data-form="${name}">${fields}<div class="modal-error" role="alert"></div><div class="form-actions"><button class="btn" type="button" data-action="close-modal">Abbrechen</button><button class="btn primary" type="submit">${e(submit)}</button></div></form></div>`);}
async function openDocument(id){const doc=await api(base()+'/documents/'+id);state.doc=doc;const editable=can('editor')&&doc.can_edit!==false&&doc.status!=='processing';const fields=field('Titel','title',doc.title,'text','required maxlength="255"')+selectField('Ordner','folder_id',[['','Nicht zugeordnet'],...state.folders.map(f=>[f.id,f.name])],doc.folder_id||'')+selectField('Dokumenttyp','doc_type',['Rechnung','Vertrag','Lieferschein','Sonstiges'].map(s=>[s,s]),doc.doc_type)+field('Lieferant / Absender','supplier',doc.supplier,'text','maxlength="150"')+`<div class="form-grid">${field('Betrag (EUR)','amount',doc.amount||'','text','inputmode="decimal" placeholder="0,00"')}${field('Fällig am','due_date',doc.due_date||'','date')}</div>`+field('Tags (mit Komma trennen)','tags',(doc.tags||[]).join(', '),'text','maxlength="1600"')+`<label class="checkbox"><input type="checkbox" name="paid" ${doc.paid?'checked':''}>Als bezahlt / erledigt markieren</label>`;modal(doc.title,`<div class="document-view"><section class="preview-pane"><div class="preview-tabs"><button class="btn small" data-action="preview-original">${icon('file')}Original</button><button class="btn small" data-action="preview-text">${icon('search')}Erkannter Text</button></div><div id="preview-area">${previewOriginal(doc)}</div></section><aside class="document-metadata"><div class="section-row"><h2>Dokumentdetails</h2>${statusBadge(doc)}</div>${doc.error?`<div class="error-message">${e(doc.error)}</div>`:''}<form data-form="document" data-id="${doc.id}"><fieldset ${editable?'':'disabled'} class="document-fields">${fields}</fieldset><div class="modal-error" role="alert"></div>${editable?'<button class="btn primary" type="submit">Änderungen speichern</button>':''}</form><div class="doc-actions"><a class="btn small" href="${base()}/documents/${doc.id}/file?download=true">${icon('download')}Herunterladen</a>${can('editor')&&doc.can_edit!==false?`<button class="btn small" data-reprocess="${doc.id}" ${doc.status==='processing'?'disabled':''}>${icon('refresh')}Neu verarbeiten</button>${doc.deleted_at?`<button class="btn small" data-restore="${doc.id}">${icon('refresh')}Wiederherstellen</button>`:`<button class="btn danger small" data-trash="${doc.id}">${icon('trash')}Papierkorb</button>`}`:''}</div>${can('owner')&&!doc.deleted_at&&['ready','error'].includes(doc.status)&&doc.text?.trim()?`<button class="btn small" data-ai-preview="${doc.id}">${icon('shield')}KI mit Datenschutzprüfung</button>`:''}<div class="hash-text">SHA-256 · ${doc.sha256}</div><div class="callout">${icon('info')}Automatisch erkannte Angaben bitte prüfen. Das Original bleibt unverändert.</div></aside></div>`,true);appendDocumentTools(doc);}
function previewOriginal(doc){const url=base()+'/documents/'+doc.id+'/file';if(doc.mime==='application/pdf')return `<iframe src="${url}" title="Dokumentvorschau" referrerpolicy="same-origin"></iframe>`;if(doc.mime==='image/png'||doc.mime==='image/jpeg')return `<img src="${url}" alt="${e(doc.title)}">`;return `<pre>${e(doc.text||'Für TIFF- und Textdokumente sehen Sie hier den erkannten Text. Das Original können Sie herunterladen.')}</pre>`;}
function showTenantModal(){modal('Ihre Dokumentenräume',`<div class="modal-body">${state.me.tenants.map(t=>`<button class="tenant-choice ${state.tenant?.id===t.id?'active':''}" data-tenant="${t.id}"><div class="workspace-icon">${icon('archive')}</div><span><strong>${e(t.name)}</strong><small>${roleLabel[t.role]}</small></span>${icon('chevron')}</button>`).join('')}${state.me.tenant_creation_enabled||state.me.admin?button('new-tenant','Neuen Dokumentenraum erstellen','plus','primary'):''}</div>`);}
async function showInvitation(){try{const inv=await api('/api/invitations/'+state.invitation);state.inv=inv;modal('Einladung in einen Dokumentenraum',`<div class="modal-body"><p><b>${e(inv.tenant)}</b> lädt Sie als ${e(roleLabel[inv.role])} ein.</p><p>Diese Einladung gilt für <b>${e(inv.email)}</b>.</p><form data-form="accept-invite">${!inv.existing_user?field('Ihr Name','name','','text','required maxlength="150"')+field('Neues Passwort','password','','password','required minlength="12" autocomplete="new-password"'):!state.me?'<p>Bitte melden Sie sich zuerst mit Ihrem bestehenden Konto an.</p>':''}<div class="modal-error" role="alert"></div><div class="form-actions">${inv.existing_user&&!state.me?'<button type="button" class="btn primary" data-action="close-modal">Zur Anmeldung</button>':'<button class="btn primary">Einladung annehmen</button>'}</div></form></div>`);}catch(err){toast(err.message,true);}}
async function integrationModal(kind){const saved=state.integrations?.find(i=>i.kind===kind);const c=saved?.config||{};let fields='';if(kind==='imap')fields=field('IMAP-Server','host',c.host||'','text','required placeholder="imap.example.org"')+field('Port (TLS)','port',c.port||993,'number','required min="1" max="65535"')+field('Benutzername','username',c.username||'','text','required autocomplete="off"')+field('Passwort / App-Passwort','password',c.password||'','password','autocomplete="new-password"')+field('Postfachordner','folder',c.folder||'INBOX')+`<label class="checkbox"><input name="import_body" type="checkbox" ${c.import_body?'checked':''}>E-Mail-Texte zusätzlich als Dokument importieren</label>`;
if(kind==='caldav')fields=field('URL des Kalenders (Collection)','url',c.url||'','url','required placeholder="https://cloud.example.org/remote.php/dav/calendars/user/dms/"')+field('Benutzername','username',c.username||'','text','required')+field('Passwort / App-Passwort','password',c.password||'','password','autocomplete="new-password"');
if(kind==='ai'){const codex=await api(base()+'/codex');const provider=c.provider||'openai';fields=selectField('KI-Anbindung','provider',[['openai','OpenAI API (API-Schlüssel)'],['codex','Codex (ChatGPT-Abonnement)']],provider)+`<div data-provider-fields="openai">`+field('API-Basis-URL','base_url',c.base_url||'https://api.openai.com/v1','url','required')+field('Modell-ID','api_model',provider==='openai'?c.model||'':'','text','required placeholder="Modell aus Ihrem API-Konto"')+field('API-Schlüssel','api_key',c.api_key||'','password','autocomplete="new-password"')+`</div><div data-provider-fields="codex"><div class="callout">${icon(codex.connected?'check':'info')}${!codex.allowed?'Der Serveradmin muss Codex für diesen Dokumentenraum freigeben.':!codex.connected?'Verbinden Sie Ihr ChatGPT-Konto in der Serveradministration → Codex.':'Codex ist verbunden. Diese Auswertung nutzt Ihr ChatGPT-Abonnement und dessen Nutzungslimits.'}</div>`+selectField('Codex-Modell','codex_model',[['','Standard aus Ihrem Codex-Konto'],...codex.models.map(m=>[m.id,m.name+(m.default?' (Standard)':'')])],provider==='codex'?c.model||'':'')+`</div>`+selectField('Externe KI-Verarbeitung','privacy_mode',[['manual','Manuell: Vorschau und Freigabe je Dokument'],['automatic','Automatisch: minimierten Text übertragen']],c.privacy_mode||'automatic')+field('Maximal übertragene Zeichen','text_limit',c.text_limit||10000,'number','required min="1000" max="10000" step="100"')+`<div data-automatic-fields><label class="checkbox"><input name="automatic_consent" type="checkbox" ${c.automatic_consent?'checked':''}>Ich erlaube die automatische Übertragung bei Import und erneuter Verarbeitung, auch ohne Einzelprüfung. Namen und Anschriften können enthalten bleiben.</label><label class="checkbox"><input name="document_fallback" type="checkbox" ${c.document_fallback?'checked':''}>Wenn OCR scheitert: sämtliche Dokumentseiten automatisch an die KI übertragen</label><p class="muted">Bildseiten lassen sich nicht automatisch maskieren. Bis zu 50 Seiten und 20 MB aufbereitete Bilder; keine stille Kürzung. Originaldatei und EXIF-Metadaten bleiben lokal.</p></div><label class="checkbox"><input name="consent" type="checkbox" ${c.consent?'checked':''}>Ich stimme der externen Verarbeitung des minimierten Dokumenttexts und gegebenenfalls des aktivierten Dokument-Fallbacks zu.</label><div class="callout">${icon('shield')}OCR und Regeln laufen lokal. E-Mail-Adressen, Bankverbindungen und typische Telefonnummern oder Kennungen werden vor Textübertragungen maskiert. Beim vollständigen Dokument-Fallback werden Bildinhalte ohne Maskierung übertragen. Die Maskierung ist keine vollständige Anonymisierung. Prüfen Sie insbesondere Namen und Anschriften. Die Verarbeitung beim Anbieter richtet sich nach Ihrem Konto und dessen Datenkontrollen.</div>`;}
if(kind==='folder')fields=`<div class="import-path"><small>Scanner-Zielordner auf dem Server</small><code>${e(saved?.paths?.incoming||'')}</code></div>`+selectField('Nach erfolgreichem Import','after_import',[['delete','Quelldatei löschen'],['archive','Nach Verarbeitet verschieben']],c.after_import||'delete')+field('Wartezeit nach letzter Dateiänderung (Sekunden)','settle_seconds',c.settle_seconds||30,'number','required min="5" max="3600"')+selectField('Ablage im DMS','folder_id',[['','Posteingang (Standard)'],...state.folders.map(f=>[f.id,f.name])],c.folder_id||'')+`<p class="muted">Original und Datenbankeintrag werden zuerst gesichert. OCR und Ablageregeln laufen anschließend im Hintergrund. Bei Fehlern und Duplikaten bleibt die Quelldatei erhalten.</p>${saved?.errors?.length?`<div class="import-errors"><strong>Zurückbehaltene Dateien</strong>${saved.errors.map(r=>`<p><b>${e(r.filename)}</b><br>${e(r.error)}</p>`).join('')}</div>`:''}`;
formModal({folder:'Scanner-Importordner',imap:'E-Mail-Import',caldav:'CalDAV-Kalender',ai:'KI-Metadaten'}[kind],'integration',`<input type="hidden" name="kind" value="${kind}">${fields}<label class="checkbox"><input name="enabled" type="checkbox" ${saved?.enabled?'checked':''}>Integration aktivieren</label>`,kind==='folder'?'Importeinstellungen speichern':'Verbindung speichern',kind==='folder'?'Prüfung etwa alle 30 Sekunden. Legen Sie fertige PDF-, Bild- oder Textdateien direkt im angezeigten Ordner ab. Jeder Dokumentenraum besitzt einen eigenen Importordner.':kind==='ai'?'Wählen Sie die API mit eigenem Schlüssel oder Codex mit Ihrem verbundenen ChatGPT-Abonnement. Originaldateien bleiben im DMS.':kind==='imap'?'Das Postfach wird alle 5 Minuten geprüft. Nachrichten werden nicht gelöscht oder als gelesen markiert.':'Alle 15 Minuten werden Fälligkeiten als Termine synchronisiert. Verwenden Sie einen eigenen Kalender für das DMS.');if(kind==='ai'){toggleAiProvider();toggleAiPrivacy();}}
async function authModal(kind){const c=await api('/api/admin/auth/'+kind);let fields='';if(kind==='oidc')fields=field('Discovery-URL','discovery_url',c.discovery_url||'','url','required placeholder="https://id.example.org/.well-known/openid-configuration"')+field('Client-ID','client_id',c.client_id||'','text','required')+field('Client-Secret','client_secret',c.client_secret||'','password','autocomplete="new-password"')+field('Redirect-URI','redirect_uri',c.redirect_uri||location.origin+'/api/auth/oidc/callback','url','required');else fields=field('LDAP-Host','host',c.host||'','text','required')+`<div class="form-grid">${field('Port','port',c.port||636,'number','required min="1" max="65535"')}${selectField('TLS-Verbindung','transport',[['ldaps','LDAPS'],['starttls','StartTLS']],c.transport||'ldaps')}</div>`+field('Basis-DN','base_dn',c.base_dn||'','text','required placeholder="DC=example,DC=org"')+field('Bind-DN (Lesekonto)','bind_dn',c.bind_dn||'','text','required')+field('Bind-Passwort','bind_password',c.bind_password||'','password','autocomplete="new-password"')+field('Benutzersuchfilter','filter',c.filter||'(mail={email})')+field('CA-Datei im Container (optional)','ca_file',c.ca_file||'');formModal(kind==='oidc'?'OpenID Connect':'LDAP / Microsoft Active Directory','auth-config',`<input type="hidden" name="kind" value="${kind}">${fields}<label class="checkbox"><input name="enabled" type="checkbox" ${Object.keys(c).length?'checked':''}>Anmeldung aktivieren</label>`,'Konfiguration speichern',kind==='oidc'?'Der Anbieter muss verifizierte E-Mail-Adressen liefern. Bestehende lokale Konten werden nur bei aktiver Anmeldung verknüpft.':'Der Server muss ein vertrauenswürdiges TLS-Zertifikat liefern. Neue Konten benötigen eine Einladung oder eine aktivierte Registrierung.');}
async function navigate(page){state.page=page;state.q='';state.folder='';state.type='';state.status='';state.offset=0;await renderApp();}
async function refresh(){await renderApp();}
async function uploadFiles(files){if(!can('editor'))return;let success=0;for(const file of files){const data=new FormData();data.append('file',file);try{await api(base()+'/documents',{method:'POST',body:data});success++;}catch(err){toast(file.name+': '+err.message,true);}}if(success)toast(`${success} Dokument${success===1?'':'e'} hochgeladen. Die Texterkennung startet automatisch.`);await refresh();}
function confirmModal(title,text,action,id){modal(title,`<div class="modal-body"><p>${e(text)}</p><div class="form-actions"><button class="btn" data-action="close-modal">Abbrechen</button><button class="btn danger" data-confirm-action="${action}" data-id="${e(id)}">Bestätigen</button></div></div>`);}

document.addEventListener('click',async event=>{const target=event.target.closest('button,a,[data-action],[data-doc]');if(!target)return;try{
 if(target.dataset.confirmAction){await confirmedAction(target.dataset.confirmAction,target.dataset.id);return;}
 if(target.dataset.page){if(!state.tenant&&!['admin','systemStatus'].includes(target.dataset.page)){renderOnboarding();return;}await navigate(target.dataset.page);return;}
 if(target.dataset.tenant){state.tenant=state.me.tenants.find(t=>t.id===target.dataset.tenant);localStorage.setItem('dms_tenant',state.tenant.id);state.page='dashboard';state.q='';state.folder='';$('#modal').close();await refresh();return;}
 if(target.dataset.folder){state.page='documents';state.folder=target.dataset.folder;state.q='';state.offset=0;await refresh();return;}
 const docId=target.dataset.openDoc||target.closest('[data-doc]')?.dataset.doc;if(docId){await openDocument(docId);return;}
 if(target.dataset.aiPreview){await aiReviewModal(target.dataset.aiPreview);return;}
 if(target.dataset.aiEdit){await aiReviewModal(state.aiReview.id,state.aiReview.text);return;}
 if(target.dataset.integration){await integrationModal(target.dataset.integration);return;}
 if(target.dataset.namePlaceholder){insertNamePlaceholder(target.dataset.namePlaceholder);return;}
 if(target.dataset.codexAction){target.disabled=true;try{await api('/api/admin/codex/'+target.dataset.codexAction,{method:'POST'});await updateCodexStatus();}finally{target.disabled=false;}return;}
 if(target.dataset.authConfig){await authModal(target.dataset.authConfig);return;}
 if(target.dataset.runIntegration){target.disabled=true;toast('Synchronisierung gestartet …');const result=await api(base()+'/integrations/'+target.dataset.runIntegration+'/run',{method:'POST'});toast(result.status,result.status.includes('fehlgeschlagen'));await refresh();return;}
 if(target.dataset.editRule){ruleModal(state.rules.find(r=>r.id===target.dataset.editRule));return;}
 if(target.dataset.removeRule){confirmModal('Regel löschen','Die Regel wird entfernt. Bereits abgelegte Dokumente behalten ihren Ordner.','remove-rule',target.dataset.removeRule);return;}
 if(target.dataset.removeFolder){confirmModal('Ordner löschen','Dokumente bleiben erhalten und werden als nicht zugeordnet angezeigt.','remove-folder',target.dataset.removeFolder);return;}
 if(target.dataset.removeMember){confirmModal('Mitglied entfernen','Das Mitglied verliert den Zugriff auf diesen Dokumentenraum.','remove-member',target.dataset.removeMember);return;}
 if(target.dataset.removeDomain){confirmModal('Domain entfernen','Die Domainzuordnung wird entfernt. DNS-Einträge bleiben unverändert.','remove-domain',target.dataset.removeDomain);return;}
 if(target.dataset.toggleUser){confirmModal('Kontostatus ändern','Aktive Sitzungen werden beendet. Die Dokumente bleiben erhalten.','toggle-user',target.dataset.toggleUser);return;}
 if(target.dataset.trash){confirmModal('In Papierkorb verschieben','Sie können das Dokument später wiederherstellen.','trash',target.dataset.trash);return;}
 if(target.dataset.restore){await api(base()+'/documents/'+target.dataset.restore+'/restore',{method:'POST'});$('#modal').close();toast('Dokument wiederhergestellt.');await refresh();return;}
 if(target.dataset.reprocess){await api(base()+'/documents/'+target.dataset.reprocess+'/reprocess',{method:'POST'});$('#modal').close();toast('Verarbeitung erneut gestartet.');await refresh();return;}
 if(target.dataset.paid){const d=await api(base()+'/documents/'+target.dataset.paid);await api(base()+'/documents/'+d.id,{method:'PUT',body:docPayload(d,true)});toast('Als bezahlt markiert.');await refresh();return;}
 if(target.dataset.quota){const t=state.admin.tenants.find(t=>t.id===target.dataset.quota);formModal('Speicherlimit ändern','quota',`<input type="hidden" name="tenant_id" value="${t.id}">${field('Speicherlimit (MB)','quota_mb',t.quota_mb,'number','required min="1" max="100000000"')}`);return;}
 if(target.dataset.roleUser){const m=state.members.find(m=>m.id===target.dataset.roleUser);formModal('Berechtigungen ändern','role',`<input type="hidden" name="user_id" value="${m.id}">${selectField('Rolle','role',Object.entries(roleLabel),m.role)}`,'Rechte speichern',m.name);return;}
 const action=target.dataset.action;
 switch(action){case 'close-modal':$('#modal').close();break;case 'retry-init':await init();break;case 'show-login':renderLogin();break;case 'show-register':renderLogin(true);break;case 'mobile-menu':$('.shell').classList.toggle('menu-open');break;case 'theme':setTheme(state.theme==='dark'?'light':'dark');target.innerHTML=icon(state.theme==='dark'?'sun':'moon');break;case 'theme-light':case 'theme-dark':case 'theme-blue':setTheme(action.slice(6));showAccount();break;case 'switch-tenant':showTenantModal();break;case 'new-tenant':formModal('Dokumentenraum erstellen','tenant',field('Name des Dokumentenraums','name','','text','required maxlength="150" placeholder="Zum Beispiel: Mein Archiv"'),'Raum erstellen','Jeder Dokumentenraum hat eine eigene Ablage, eigene Mitglieder und eigene Zugriffsrechte.');break;case 'upload':$('#file-input').click();break;case 'all-documents':await navigate('documents');break;case 'new-folder':formModal('Ordner erstellen','folder',field('Ordnername','name','','text','required maxlength="150"'));break;case 'new-rule':ruleModal();break;case 'new-invite':formModal('Mitglied einladen','invite',field('E-Mail-Adresse','email','','email','required')+selectField('Berechtigung','role',Object.entries(roleLabel).filter(([k])=>roleLevel[k]<roleLevel[state.tenant.role])), 'Einladungslink erstellen','Der Link ist 7 Tage gültig. Sie können ihn anschließend an das Mitglied weitergeben.');break;case 'apply-rules':{const result=await api(base()+'/rules/apply',{method:'POST'});toast(`${result.changed} ${result.changed===1?'Dokument umbenannt oder neu zugeordnet':'Dokumente umbenannt oder neu zugeordnet'}.`);await refresh();break;}case 'new-domain':formModal('Domain hinzufügen','domain',field('Hostname (ohne Protokoll und Port)','host','','text','required placeholder="dms.example.org"')+selectField('Bevorzugter Dokumentenraum','tenant_id',[['','Keine feste Zuordnung'],...state.admin.tenants.map(t=>[t.id,t.name])]));break;case 'account':showAccount();break;case 'password':formModal('Passwort ändern','password',field('Aktuelles Passwort','current_password','','password','required autocomplete="current-password"')+field('Neues Passwort','password','','password','required minlength="12" autocomplete="new-password"'),'Passwort ändern','Mindestens 12 Zeichen. Alle bisherigen Sitzungen werden beendet.');break;case 'link-oidc':location.href='/api/auth/oidc';break;case 'logout':await api('/api/auth/logout',{method:'POST'});state.me=null;state.tenant=null;$('#modal').close();renderLogin();break;case 'preview-original':$('#preview-area').innerHTML=previewOriginal(state.doc);break;case 'preview-text':$('#preview-area').innerHTML=`<pre>${e(state.doc.text||'Noch kein Text verfügbar. Die Verarbeitung läuft oder konnte keinen Text erkennen.')}</pre>`;break;case 'refresh-page':await refresh();break;case 'clear-filter':state.q='';state.folder='';state.type='';state.status='';state.offset=0;await refresh();break;case 'prev-page':state.offset=Math.max(0,state.offset-50);await refresh();break;case 'next-page':state.offset+=50;await refresh();break;case 'copy-invite':try{await navigator.clipboard.writeText(state.inviteLink);toast('Einladungslink kopiert.');}catch{toast('Bitte den angezeigten Link markieren und kopieren.',true);}break;case 'install-pwa':if(state.installPrompt){await state.installPrompt.prompt();state.installPrompt=null;}break;
 }
}catch(err){toast(err.message,true);target.disabled=false;}});
function showAccount(){modal('Ihr Konto',`<div class="modal-body"><p><b>${e(state.me.name)}</b><br>${e(state.me.email)}</p><h3>Erscheinungsbild</h3><div class="theme-choices">${[['light','Hell'],['dark','Dunkel'],['blue','Blau']].map(([v,l])=>`<button class="${state.theme===v?'active':''}" data-action="theme-${v}">${l}</button>`).join('')}</div>${button('password','Passwort ändern','key')}<button class="btn" data-feature-action="mfa">${icon('shield')}Zwei-Faktor-Anmeldung</button>${state.public.oidc_enabled?button('link-oidc','Mit OIDC verknüpfen','link'):''}${state.installPrompt?button('install-pwa','Als App installieren','download'):''}<div class="form-actions">${button('logout','Abmelden','logout')}</div></div>`);}
async function confirmedAction(action,id){const urls={'remove-rule':base()+'/rules/'+id,'remove-folder':base()+'/folders/'+id,'remove-member':base()+'/members/'+id,'remove-domain':'/api/admin/domains/'+encodeURIComponent(id),'toggle-user':'/api/admin/users/'+id+'/toggle','trash':base()+'/documents/'+id};await api(urls[action],{method:action==='toggle-user'?'POST':'DELETE'});$('#modal').close();toast('Änderung gespeichert.');await refresh();}
function docPayload(d,paid=d.paid){return {title:d.title,folder_id:d.folder_id||null,supplier:d.supplier||'',doc_type:d.doc_type||'Sonstiges',tags:d.tags||[],amount:d.amount||null,due_date:d.due_date||null,paid};}

document.addEventListener('submit',async event=>{const form=event.target;if(!form.dataset.form)return;event.preventDefault();const data=Object.fromEntries(new FormData(form));const submit=$('button[type="submit"],button:not([type])',form);if(submit)submit.disabled=true;const error=$('.modal-error',form);if(error)error.textContent='';try{let close=true;switch(form.dataset.form){case 'ai-preview':{const review=await api(base()+'/documents/'+state.aiReview.id+'/ai-preview',{method:'POST',body:{text:data.text}});state.aiReview={...review,id:state.aiReview.id};showAiSend();close=false;break;}case 'ai-send':{const review=state.aiReview;await api(base()+'/documents/'+review.id+'/ai',{method:'POST',body:{text:review.text,token:review.token,confirmed:form.elements.confirmed.checked}});toast('KI-Metadaten übernommen. Bitte fachlich prüfen.');await refresh();await openDocument(review.id);close=false;break;}case 'login':case 'register':{const result=await api('/api/auth/'+form.dataset.form,{method:'POST',body:data});if(result.mfa_required){renderMfaLogin();close=false;break;}}state.me=await api('/api/me');chooseDefaultTenant();await renderApp();if(state.invitation)await showInvitation();close=false;break;case 'global-search':state.q=data.q;state.page='documents';state.folder='';state.offset=0;await refresh();close=false;break;case 'filter':state.q=data.q;state.type=data.doc_type;state.folder=state.page==='inbox'?state.folders.find(f=>f.name==='Eingang')?.id||'':data.folder;state.status=data.status;state.offset=0;await refresh();close=false;break;case 'tenant':{const t=await api('/api/tenants',{method:'POST',body:data});state.me=await api('/api/me');state.tenant=state.me.tenants.find(x=>x.id===t.id);localStorage.setItem('dms_tenant',t.id);state.page='dashboard';toast('Dokumentenraum erstellt.');await refresh();break;}case 'folder':await api(base()+'/folders',{method:'POST',body:data});toast('Ordner erstellt.');await refresh();break;case 'rule':{const id=data.rule_id;delete data.rule_id;data.priority=Number(data.priority);data.folder_id=data.folder_id||null;data.filename_template=data.filename_template||null;data.contains=data.field==='all'?'':data.contains;data.enabled=form.elements.enabled.checked;await api(base()+'/rules'+(id?'/'+id:''),{method:id?'PUT':'POST',body:data});toast('Regel gespeichert.');await refresh();break;}case 'invite':{const r=await api(base()+'/invitations',{method:'POST',body:data});state.inviteLink=location.origin+r.path;modal('Einladung erstellt',`<div class="modal-body"><p>Einladung für <b>${e(data.email)}</b>. Geben Sie diesen Link an das Mitglied weiter. Gültig bis ${dateFormat(r.expires_at)}.</p><div class="invitation-link">${e(state.inviteLink)}</div><div class="form-actions">${button('copy-invite','Link kopieren','link','primary')}</div></div>`);close=false;break;}case 'accept-invite':await api('/api/invitations/accept',{method:'POST',body:{...data,token:state.invitation}});state.invitation=null;history.replaceState({},'', '/');state.me=await api('/api/me');chooseDefaultTenant();await refresh();toast('Einladung angenommen.');break;case 'document':data.tags=data.tags.split(',').map(s=>s.trim()).filter(Boolean);data.folder_id=data.folder_id||null;data.amount=data.amount||null;data.due_date=data.due_date||null;data.paid=form.elements.paid.checked;await api(base()+'/documents/'+form.dataset.id,{method:'PUT',body:data});toast('Dokument aktualisiert.');await refresh();break;case 'codex-tenants':await api('/api/admin/codex/tenants',{method:'PUT',body:{tenant_ids:new FormData(form).getAll('tenant_ids')}});toast('Codex-Freigaben gespeichert.');await refresh();close=false;break;case 'integration':{const kind=data.kind;delete data.kind;const enabled=form.elements.enabled.checked;delete data.enabled;if(kind==='imap'){data.port=Number(data.port);data.import_body=form.elements.import_body.checked;}if(kind==='folder'){data.settle_seconds=Number(data.settle_seconds);data.folder_id=data.folder_id||null;}if(kind==='ai'){data.consent=form.elements.consent.checked;data.automatic_consent=data.privacy_mode==='automatic'&&form.elements.automatic_consent.checked;data.document_fallback=data.privacy_mode==='automatic'&&form.elements.document_fallback.checked;data.text_limit=Number(data.text_limit);data.model=data.provider==='codex'?data.codex_model:data.api_model;delete data.api_model;delete data.codex_model;}await api(base()+'/integrations/'+kind,{method:'PUT',body:{enabled,config:data}});toast('Integration gespeichert.');await refresh();break;}case 'settings':data.registration_enabled=form.elements.registration_enabled.checked;data.tenant_creation_enabled=form.elements.tenant_creation_enabled.checked;data.ai_external_blocked=form.elements.ai_external_blocked.checked;await api('/api/admin/settings',{method:'PUT',body:data});state.public=await api('/api/public');document.title=state.public.app_name;state.me=await api('/api/me');toast('Systemeinstellungen gespeichert.');await refresh();close=false;break;case 'domain':data.tenant_id=data.tenant_id||null;await api('/api/admin/domains',{method:'POST',body:data});toast('Domain gespeichert.');await refresh();break;case 'quota':await api('/api/admin/tenants/'+data.tenant_id+'/quota',{method:'PUT',body:{quota_mb:Number(data.quota_mb)}});toast('Speicherlimit gespeichert.');await refresh();break;case 'role':await api(base()+'/members/'+data.user_id,{method:'PUT',body:{role:data.role}});state.me=await api('/api/me');state.tenant=state.me.tenants.find(t=>t.id===state.tenant.id);toast('Berechtigung gespeichert.');await refresh();break;case 'rename-tenant':await api(base(),{method:'PUT',body:data});state.me=await api('/api/me');state.tenant=state.me.tenants.find(t=>t.id===state.tenant.id);toast('Name gespeichert.');await refresh();close=false;break;case 'password':await api('/api/me/password',{method:'PUT',body:data});toast('Passwort geändert.');break;case 'auth-config':{const kind=data.kind;delete data.kind;const enabled=form.elements.enabled.checked;delete data.enabled;if(kind==='ldap')data.port=Number(data.port);await api('/api/admin/auth/'+kind,{method:'PUT',body:{enabled,config:data}});state.public=await api('/api/public');toast('Authentifizierung gespeichert.');await refresh();break;}}
if(close)$('#modal').close();}catch(err){if(error)error.textContent=err.message;else if(['login','register'].includes(form.dataset.form))$('#auth-error').innerHTML=`<div class="error-message" role="alert">${e(err.message)}</div>`;else toast(err.message,true);}finally{if(submit)submit.disabled=false;}});
$('#file-input').addEventListener('change',async event=>{await uploadFiles([...event.target.files]);event.target.value='';});
document.addEventListener('dragover',event=>{if(event.dataTransfer.types.includes('Files')&&can('editor')){event.preventDefault();$$('[data-drop]').forEach(el=>el.classList.add('drag'));}});
document.addEventListener('dragleave',event=>{if(!event.relatedTarget)$$('[data-drop]').forEach(el=>el.classList.remove('drag'));});
document.addEventListener('drop',async event=>{if(can('editor')&&event.dataTransfer.files.length){event.preventDefault();$$('[data-drop]').forEach(el=>el.classList.remove('drag'));await uploadFiles([...event.dataTransfer.files]);}});
document.addEventListener('keydown',event=>{if(event.key==='Escape')$('.shell')?.classList.remove('menu-open');if((event.ctrlKey||event.metaKey)&&event.key==='k'){event.preventDefault();$('.search-field input')?.focus();}if(event.key==='Enter'&&event.target.matches('[data-drop]'))$('#file-input').click();});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.target.close();}});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();state.installPrompt=event;});
let polling=false,pollTicks=0;
setInterval(async()=>{if(polling||!state.me||!state.tenant||document.hidden||$('#modal').open||document.activeElement?.matches('input,textarea,select'))return;if(!state.stats?.queued&&++pollTicks%3!==0)return;polling=true;const tenantId=state.tenant.id,loadId=state.loadId;try{const stats=await api(base()+'/stats');if(state.tenant?.id===tenantId&&state.loadId===loadId&&(state.stats?.queued>0||JSON.stringify(stats)!==JSON.stringify(state.stats)))await refresh();}catch{}finally{polling=false;}},10000);
init();

function ruleModal(r={}){
 formModal(r.id?'Regel bearbeiten':'Regel erstellen','rule',`<input type="hidden" name="rule_id" value="${r.id||''}">`+field('Name der Regel','name',r.name||'','text','required maxlength="150" placeholder="Rechnungen benennen"')+selectField('Bedingung','field',[['all','Alle Dokumente'],['text','Dokumenttext enthält …'],['supplier','Lieferant enthält …'],['doc_type','Dokumenttyp enthält …'],['title','Titel enthält …'],['filename','Dateiname enthält …']],r.field||'doc_type')+`<div data-rule-condition>${field('Suchtext','contains',r.contains||'','text','required maxlength="150" placeholder="Rechnung"')}</div>`+selectField('Zielordner (optional)','folder_id',[['','Ordner beibehalten'],...state.folders.map(f=>[f.id,f.name])],r.folder_id||'')+field('Dateinamen-Vorlage (optional, ohne Endung)','filename_template',r.filename_template||'','text','maxlength="255" placeholder="{date}_{supplier}_{doc_type}" autocomplete="off" spellcheck="false"')+`<div class="name-placeholders">${[['date','Importdatum'],['supplier','Lieferant'],['doc_type','Dokumenttyp'],['original_name','Originalname'],['due_date','Fälligkeit'],['title','Titel'],['id','Dokument-ID'],['version','Version'],['amount','Betrag'],['year','Importjahr'],['month','Importmonat']].map(([key,label])=>`<button type="button" class="name-placeholder" data-name-placeholder="{${key}}" title="${e(label)}">${e(label)} <code>{${key}}</code></button>`).join('')}</div><div class="name-preview"><span>Vorschau mit Beispieldaten</span><output data-rule-name-preview></output></div><p class="name-help">Wählen Sie mindestens einen Zielordner oder eine Namensvorlage. Die Dateiendung wird automatisch ergänzt. Ohne alle benötigten Angaben wartet die Umbenennung. Bei gleichen Namen ergänzt das DMS die Dokument-ID.</p>`+field('Priorität (kleinere Zahl zuerst)','priority',r.priority??100,'number','required min="0" max="9999"')+`<label class="checkbox"><input name="enabled" type="checkbox" ${r.enabled!==false?'checked':''}>Regel aktivieren</label>`);
 updateRuleForm();
}
function updateRuleForm(){
 const form=$('form[data-form="rule"]');if(!form)return;
 const all=form.elements.field.value==='all';$('[data-rule-condition]',form).hidden=all;form.elements.contains.required=!all;
 const template=form.elements.filename_template.value,preview=$('[data-rule-name-preview]',form);
 if(!template.trim()){preview.textContent='Eine Namensvorlage eingeben, um das Beispiel zu sehen.';return;}
 const day=new Date().toISOString().slice(0,10),examples={date:day,year:day.slice(0,4),month:day.slice(5,7),supplier:'Beispiel GmbH',doc_type:'Rechnung',original_name:'Scan_001',due_date:day,title:'Rechnung Oktober',id:'6f780819-42ef-4f3d-8846-61484367b217',version:'2',amount:'125.50'};
 let unknown=false;const rendered=template.replace(/\{([a-z_]+)\}/g,(match,key)=>{if(!(key in examples)){unknown=true;return match;}return examples[key];});
 preview.textContent=unknown||/[{}]/.test(rendered)?'Unbekannter oder ungültiger Platzhalter.':rendered+'.pdf';
}
function insertNamePlaceholder(value){const input=$('form[data-form="rule"] input[name="filename_template"]');if(!input)return;input.setRangeText(value,input.selectionStart,input.selectionEnd,'end');input.focus();updateRuleForm();}
document.addEventListener('input',event=>{if(event.target.name==='filename_template')updateRuleForm();});
document.addEventListener('change',event=>{if(event.target.closest('form[data-form="rule"]'))updateRuleForm();});

function toggleAiProvider(){const form=$('form[data-form="integration"]');if(!form||form.elements.kind.value!=='ai')return;const provider=form.elements.provider.value;$$('[data-provider-fields]',form).forEach(block=>{const active=block.dataset.providerFields===provider;block.hidden=!active;$$('input,select',block).forEach(input=>input.disabled=!active);});}
document.addEventListener('change',event=>{if(event.target.name==='provider')toggleAiProvider();if(event.target.name==='privacy_mode')toggleAiPrivacy();});
function codexWindowHtml(w,slot){
 if(!w)return '';
 const mins=w.duration_minutes;let duration=slot==='primary'?'Primäres Zeitfenster':'Sekundäres Zeitfenster';
 if(Number.isFinite(mins)&&mins>0){const days=mins/1440,hours=mins/60;duration=Number.isInteger(days)?days+' '+(days===1?'Tag':'Tage'):Number.isInteger(hours)?hours+' '+(hours===1?'Stunde':'Stunden'):mins.toLocaleString('de-DE')+' Minuten';}
 const known=Number.isFinite(w.used_percent),used=known?w.used_percent:0;
 const reset=Number.isFinite(w.resets_at)?new Date(w.resets_at*1000):null;
 return `<div class="codex-window"><div class="codex-window-title"><span>${e(duration)}</span><strong>${known?e(w.remaining_percent.toLocaleString('de-DE'))+' % frei':'Auslastung unbekannt'}</strong></div>${known?`<div class="progress" role="progressbar" aria-label="Verbrauch · ${e(duration)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${used}"><div class="progress-bar ${used>=90?'quota-high':used>=75?'quota-warning':''}" data-width="${used}"></div></div>`:''}<div class="codex-window-detail"><span>${known?e(used.toLocaleString('de-DE'))+' % verbraucht':'Kein Verbrauchswert geliefert'}</span><span>${reset&&!Number.isNaN(reset.getTime())?'Zurücksetzung: '+e(reset.toLocaleString('de-DE',{dateStyle:'short',timeStyle:'short'})):'Zurücksetzung unbekannt'}</span></div></div>`;
}
function codexUsageHtml(c){
 const u=c.usage;
 if(!c.connected)return `<div class="codex-usage"><h3>Codex-Kontingent</h3><p>Verbinden Sie Ihr ChatGPT-Konto, um die Nutzungslimits anzuzeigen.</p></div>`;
 const buckets=u?.buckets||[];
 return `<div class="codex-usage"><h3>Codex-Kontingent</h3><p>Kontoweite Nutzung, einschließlich anderer Codex-Anwendungen und aller freigegebenen Dokumentenräume.</p>${u?.status==='unavailable'?`<p class="quota-notice">${e(u.message||'Kontingent derzeit nicht abrufbar.')}</p>`:!buckets.length?'<p>OpenAI liefert derzeit keine Kontingentdaten.</p>':buckets.map(b=>`<section class="codex-bucket"><div class="codex-bucket-title"><strong>${e(b.name||b.id||'Codex')}</strong>${b.limit_reached||b.spend_control_reached?'<span class="badge red">Nutzungslimit erreicht</span>':''}</div>${codexWindowHtml(b.primary,'primary')}${codexWindowHtml(b.secondary,'secondary')}${!b.primary&&!b.secondary?'<p>Keine Zeitfenster gemeldet.</p>':''}${b.credits?`<p class="codex-credits">Zusätzliche Credits: ${b.credits.unlimited?'unbegrenzt':b.credits.balance!==null?e(b.credits.balance):b.credits.has_credits===false?'keine verfügbar':'Bestand unbekannt'}</p>`:''}</section>`).join('')}${u?.ordinary_usage_allowed===false?'<p class="quota-notice">Codex meldet aktuell keine verfügbare inklusive Nutzung.</p>':''}${u?.checked_at?`<small>Stand: ${e(new Date(u.checked_at*1000).toLocaleTimeString('de-DE'))} · Automatische Aktualisierung etwa jede Minute. Zeitangaben in Ihrer lokalen Zeitzone.</small>`:''}</div>`;
}

function codexStatusHtml(c){return `<span class="badge ${c.connected?'':'gray'}">${c.connected?'Mit ChatGPT verbunden':c.available?'Noch nicht verbunden':'Dienst nicht erreichbar'}</span>${c.connected?`<p>${e(c.email||'ChatGPT-Konto')}${c.plan?' · '+e(c.plan):''}</p>`:''}${codexUsageHtml(c)}${c.message?`<p class="error-message">${e(c.message)}</p>`:''}${c.login?.status==='pending'?`<div class="codex-login"><p>Öffnen Sie OpenAI und geben Sie diesen Code ein:</p><strong class="device-code">${e(c.login.user_code)}</strong><a class="btn primary" href="https://auth.openai.com/codex/device" target="_blank" rel="noopener noreferrer">${icon('link')}Bei OpenAI anmelden</a><small>Falls nötig, Geräteanmeldung in den Sicherheitseinstellungen Ihres ChatGPT-Kontos aktivieren. Der Verbindungsstatus aktualisiert sich automatisch.</small></div>`:''}${c.login?.status==='error'?`<p class="error-message">${e(c.login.message)}</p>`:''}<div class="form-actions">${c.available?`<button class="btn ${c.connected?'':'primary'}" data-codex-action="login">${icon('key')}${c.connected?'Konto neu verbinden':c.login?.status==='pending'?'Neuen Anmeldecode anfordern':'Mit ChatGPT verbinden'}</button>${c.connected||c.login?.status==='pending'?`<button class="btn" data-codex-action="logout">${icon('logout')}Verbindung trennen</button>`:''}`:''}</div>`;}
let codexPolling=false;
async function updateCodexStatus(){const status=await api('/api/admin/codex');const panel=$('#codex-status');if(panel){panel.innerHTML=codexStatusHtml(status);applyWidths();}}
setInterval(async()=>{if(codexPolling||state.page!=='admin'||!state.me?.admin||document.hidden||!$('#codex-status'))return;codexPolling=true;try{await updateCodexStatus();}catch{}finally{codexPolling=false;}},5000);

function toggleAiPrivacy(){const form=$('form[data-form="integration"]');if(!form||form.elements.kind.value!=='ai')return;const active=form.elements.privacy_mode.value==='automatic';const block=$('[data-automatic-fields]',form);block.hidden=!active;form.elements.automatic_consent.disabled=!active;form.elements.automatic_consent.required=active;form.elements.document_fallback.disabled=!active;}
async function aiReviewModal(id,text){const review=await api(base()+'/documents/'+id+'/ai-preview',{method:'POST',body:text===undefined?{}:{text}});state.aiReview={...review,id};modal('KI · Dokumenttext prüfen',`<form class="modal-body" data-form="ai-preview"><p>OCR und Original bleiben im DMS. Entfernen Sie Namen, Anschriften und andere vertrauliche Stellen aus dem folgenden Text. Die automatische Maskierung erfasst nicht alle personenbezogenen Angaben.</p>${aiPrivacySummary(review)}<div class="field"><label for="ai-draft">Text für die KI · kürzen oder weitere Stellen entfernen</label><textarea id="ai-draft" name="text" class="ai-text" maxlength="10000" required spellcheck="false" autocomplete="off">${e(review.text)}</textarea></div><div class="modal-error" role="alert"></div><div class="form-actions"><button type="button" class="btn" data-action="close-modal">Abbrechen</button><button type="submit" class="btn primary">Übertragung prüfen</button></div></form>`,true);}
function aiPrivacySummary(review){return `<div class="callout">${icon('shield')}Empfänger: ${e(review.target)} · ${review.text.length.toLocaleString('de-DE')} Zeichen${review.truncated?' · Text gekürzt':''}. ${Object.entries(review.redactions).map(([name,count])=>e(name)+': '+count).join(' · ')||'Keine typischen sensiblen Angaben erkannt.'}</div>`;}
function showAiSend(){const review=state.aiReview;modal('KI · Übertragung freigeben',`<form class="modal-body" data-form="ai-send">${aiPrivacySummary(review)}<p>Dieser Text wird übertragen. Prüfen Sie ihn nochmals. Originaldatei, Dateiname und Benutzerkonto werden nicht mitgesendet.</p><div class="field"><label for="ai-final">Endgültige Textvorschau</label><textarea id="ai-final" class="ai-text" readonly spellcheck="false">${e(review.text)}</textarea></div><label class="checkbox"><input type="checkbox" name="confirmed" required>Ich habe den Text geprüft und gebe diese Übertragung frei.</label><div class="modal-error" role="alert"></div><div class="form-actions"><button type="button" class="btn" data-ai-edit="true">Text bearbeiten</button><button type="submit" class="btn primary">Jetzt an KI übertragen</button></div></form>`,true);}
$('#modal').addEventListener('close',()=>{if($('#modal').open)return;$('#modal-content').replaceChildren();state.doc=null;state.aiReview=null;});
